3: function request(method, url, body, { token, headers = {}, ...params } = {}) {
4:     const requestHeaders = { "Content-Type": "application/json", ...headers };
5:     const hasAuthorization = Object.keys(headers).some(
6:         (name) => name.toLowerCase() === "authorization",
7:     );
8:     if (token && !hasAuthorization) {
9:         requestHeaders.Authorization = `Bearer ${token}`;
10:     }
11: 
12:     const isJsonBody = body !== null && typeof body === "object"
13:         && !(body instanceof ArrayBuffer) && !ArrayBuffer.isView(body);
14:     const payload = isJsonBody ? JSON.stringify(body) : body;
15: 
16:     return http.request(method, url, payload, {
17:         ...params,
18:         headers: requestHeaders,
19:     });
20: }
